(function(root){'use strict';
const DIMENSIONS=['app','app_token','os_name','country','country_code','region','channel','network','partner_name','campaign','campaign_network','campaign_id_network','adgroup','adgroup_network','adgroup_id_network','creative','creative_network','creative_id_network','device_type','store_type','platform','currency_code'];
const OPERATORS=['in','not_in','contains','exclude','starts_with','not_starts_with','ends_with','not_ends_with','lt','lte','gt','gte','eq','ne'];
const num=v=>v===null||v===undefined||v===''?null:Number.isFinite(Number(v))?Number(v):null;
function validDate(v){return /^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v}
function parameters(c){if(!validDate(c.from)||!validDate(c.to)||c.from>c.to)throw Error('Khoảng ngày chưa hợp lệ.');if((Date.parse(c.to)-Date.parse(c.from))/864e5>365)throw Error('Mỗi lần pull tối đa 366 ngày.');const slugs=list=>[...new Set(list)].map(s=>{if(!/^[a-zA-Z0-9_]+$/.test(s))throw Error('Metric/dimension slug không hợp lệ.');return s}).join(',');const dimensions=[c.granularity||'day',...(c.dimensions||[])];if(!['day','week','month'].includes(dimensions[0])||!c.metrics?.length)throw Error('Chọn ít nhất một metric.');const p={date_period:c.from+':'+c.to,dimensions:slugs(dimensions),metrics:slugs(c.metrics),format_dates:'false'};const rules={currency:/^[A-Z]{3}$/,utc_offset:/^[+-](?:0\d|1[0-4]):[0-5]\d$/,cohort_maturity:/^(mature|immature)$/,attribution_source:/^(first|dynamic)$/,reattributed:/^(all|true|false)$/,iap_revenue_mode:/^GROSS_(100|85|70|60)$/,ad_spend_mode:/^(adjust|network|mixed)$/,sandbox:/^(true|false)$/};for(const [k,re]of Object.entries(rules)){const v=String(c[k]??'');if(v){if(!re.test(v))throw Error('Thiết lập '+k+' chưa hợp lệ.');p[k]=v}}if(c.attribution_types?.length){if(c.attribution_types.some(s=>!['click','impression','engaged_ad'].includes(s)))throw Error('Attribution type chưa hợp lệ.');p.attribution_types=c.attribution_types.join(',')}if(c.ad_revenue_sources)p.ad_revenue_sources=c.ad_revenue_sources;if(c.period_over_period){if(!/^[a-z_]+$/.test(c.period_over_period))throw Error('Kỳ so sánh chưa hợp lệ.');p.period_over_period=c.period_over_period}for(const f of c.filters||[]){if(!/^[a-zA-Z0-9_]+$/.test(f.field)||!OPERATORS.includes(f.op)||String(f.value).length>1000)throw Error('Filter chưa hợp lệ.');const key=f.field+'__'+f.op;if(key in p)throw Error('Filter trùng: '+key);if(String(f.value).trim())p[key]=String(f.value).trim()}return p}
function filter(data,c){return data.filter(r=>{const d=String(r.day??r.week??r.month??r.date??'').slice(0,10);if(d&&(d<c.from||d>c.to))return false;return (c.filters||[]).every(f=>{const value=r[f.field];if(value==null)return false;const a=String(value).toLowerCase(),b=String(f.value).toLowerCase(),set=b.split(',').map(v=>v.trim());switch(f.op){case 'in':return set.includes(a);case 'not_in':return !set.includes(a);case 'contains':return a.includes(b);case 'exclude':return !a.includes(b);case 'starts_with':return a.startsWith(b);case 'not_starts_with':return !a.startsWith(b);case 'ends_with':return a.endsWith(b);case 'not_ends_with':return !a.endsWith(b);default:const x=num(value),y=num(f.value);return x!==null&&y!==null&&({lt:x<y,lte:x<=y,gt:x>y,gte:x>=y,eq:x===y,ne:x!==y}[f.op]??false)}})})}
function metricSpec(metric){if(['installs','clicks','impressions','cost','network_cost','adjust_cost','revenue','revenue_total','ad_revenue','iap_revenue','sessions'].includes(metric)||/^cohort_(revenue|users)_d\d+$/.test(metric))return {type:'sum'};if(metric==='cpi')return {type:'ratio',numerator:'cost',denominator:'installs'};if(metric==='ctr')return {type:'ratio',numerator:'clicks',denominator:'impressions',scale:100};return {type:'raw'}}
function aggregate(data,metric,spec=metricSpec(metric)){if(spec.type==='ratio'){const pairs=data.filter(r=>num(r[spec.numerator])!==null&&num(r[spec.denominator])!==null),a=pairs.reduce((s,r)=>s+num(r[spec.numerator]),0),b=pairs.reduce((s,r)=>s+num(r[spec.denominator]),0);return b>0?a/b*(spec.scale||1):null}const nums=data.map(r=>num(r[metric])).filter(v=>v!==null);if(!nums.length)return null;if(spec.type==='sum')return nums.reduce((a,b)=>a+b,0);if(spec.type==='mean')return nums.reduce((a,b)=>a+b,0)/nums.length;return nums.length===1?nums[0]:null}
function ltv(data,c){if(!Number.isInteger(c.horizon)||c.horizon<1||c.horizon>180||!validDate(c.observation))throw Error('LTV cần horizon và ngày dữ liệu đầy đủ hợp lệ.');const eligible=data.filter(r=>{const d=String(r.day??r.date??'');return validDate(d)&&Date.parse(d)+c.horizon*864e5<=Date.parse(c.observation)});const pairs=eligible.filter(r=>num(r[c.numerator])!==null&&num(r[c.denominator])!==null&&num(r[c.denominator])>0);return {value:aggregate(pairs,'ltv',{type:'ratio',numerator:c.numerator,denominator:c.denominator}),eligibleRows:pairs.length,excludedRows:data.length-pairs.length,users:pairs.reduce((s,r)=>s+num(r[c.denominator]),0)}}
function group(data,dimensions,metrics,specs={}){const g=new Map();data.forEach(r=>{const key=JSON.stringify(dimensions.map(d=>r[d]??'—'));if(!g.has(key))g.set(key,[]);g.get(key).push(r)});return [...g.values()].map(rows=>Object.fromEntries([...dimensions.map(d=>[d,rows[0][d]??'—']),...metrics.map(m=>[m,aggregate(rows,m,specs[m])])]))}
function unpack(input){const rows=Array.isArray(input)?input:input?.rows;if(!Array.isArray(rows)||rows.some(r=>!r||typeof r!=='object'||Array.isArray(r)))throw Error('Cần bảng report Adjust hoặc JSON {rows:[...]}.');if(rows.length>50000)throw Error('MVP nhận tối đa 50.000 dòng; thu hẹp scope.');if(input?.pagination)throw Error('Report có pagination: cần export đầy đủ hoặc thu hẹp scope, không dùng phần dữ liệu bị cắt.');return rows.map(r=>Object.fromEntries(Object.entries(r).filter(([k,v])=>k!=='attr_dependency'&&(v===null||typeof v!=='object'))))}
const api={DIMENSIONS,OPERATORS,num,validDate,parameters,filter,metricSpec,aggregate,ltv,group,unpack};if(typeof module!=='undefined')module.exports=api;else root.AdjustReport=api;
})(typeof window!=='undefined'?window:globalThis);
